import type { CarrierGuide } from './dispatch-content';
import { DISPATCH_RATE_RANGE, getDispatchRate, getDispatchRateLabel } from './dispatch-pricing';

export const CARRIER_EDUCATION_GUIDES: CarrierGuide[] = [
  {
    slug: 'truck-dispatch-service-agreement-checklist',
    title: 'Truck dispatch service agreement: a carrier review checklist',
    metaTitle: 'Truck Dispatch Service Agreement Checklist',
    description: 'Review a dispatch agreement before signing: scope, carrier approval, fee base, account access, communication, cancellation and the handover of existing loads.',
    eyebrow: 'Carrier guide · Put the working arrangement in writing',
    published: '2026-10-30', readTime: '7 minute read',
    intro: 'A truck dispatch service agreement should explain how the relationship will work on an ordinary load and when plans change. Review the actual scope, approval process and billing terms before granting access or starting a search. Use this checklist to identify questions for the provider and, where needed, your own adviser; it is a review worksheet, not a contract template.',
    highlights: ['Define the work and approval process', 'Test the fee with an example', 'Plan access and a clean handover'],
    sections: [
      { id: 'parties', title: 'Identify the parties and the equipment covered', paragraphs: ['Check the legal names, contact details and effective date. List the carrier operation and trucks covered, and identify the person authorized to approve loads and service changes. A salesperson’s description should match the agreement you are asked to sign.', 'For a fleet, decide whether every truck is included from the same date or whether trucks can be added separately. Ask how the agreement handles a replacement truck, a driver change or a period out of service. These details affect the search and can also affect billing.'] },
      { id: 'scope', title: 'Assign the work one task at a time', paragraphs: ['Separate load search, rate discussions, booking coordination, broker calls, appointment updates and document follow ups. Record which tasks the dispatcher performs, which remain with the carrier and which require another provider. “Full service” is not a substitute for that list.', 'Identify any tools, platform seats or third party charges separately. Keep load board access within the provider’s supported process. If the carrier already has factoring or bookkeeping arrangements, explain where signed documents go and who owns each remaining task.'], table: { caption: 'A practical dispatch agreement review sheet', headers: ['Term', 'Question to resolve', 'Evidence to keep'], rows: [['Load approval', 'Who may approve, decline or change a booking?', 'Named contacts and the agreed approval channel'], ['Service scope', 'Which search, communication and document tasks are included?', 'Written task list and exclusions'], ['Fees', 'Which revenue items and loads form the billing base?', 'Equipment rate and a sample calculation'], ['Accounts', 'Who owns access and how is it granted or removed?', 'Authorized user process and account owner'], ['End of service', 'What notice applies and who finishes booked work?', 'Notice terms, final load list and handover plan']] } },
      { id: 'approval', title: 'Make carrier approval workable under time pressure', paragraphs: ['A useful process states what information the dispatcher will present: route, dates, appointments, compensation, empty miles and important handling requirements. Agree how approval is recorded and what happens if the authorized carrier contact cannot answer.', 'Test the process with a changed appointment. If a broker moves delivery to the following day after you approved the load, who contacts you and who may accept the change? Discuss how the driver receives the final instructions so an old message is not mistaken for the current plan.'] },
      { id: 'fee-example', title: 'Test the billing base with actual invoice categories', paragraphs: [`Rai Dispatch’s published fees are ${DISPATCH_RATE_RANGE} by equipment. The written agreement needs to identify the applicable rate and revenue base. Ask how fuel surcharge, detention, other accessorials, cancelled loads, disputed payment and independently booked loads are treated.`, `Consider a hypothetical dry van load with $2,000 linehaul and a $300 separately stated fuel surcharge. At ${getDispatchRateLabel('dry-van')}, a $2,000 billing base produces a $${2000 * getDispatchRate('dry-van') / 100} dispatch fee; a $2,300 base produces $${2300 * getDispatchRate('dry-van') / 100}. The agreement decides which base applies. The example is a question to resolve, not a statement that either treatment applies to your contract.`, 'Ask when the fee is earned, when the invoice arrives and when payment is due. A carrier receiving load payment later should understand the timing before accepting the dispatch terms. Keep the accepted quote with the agreement so changes can be traced.'] },
      { id: 'access', title: 'Agree communication, records and account control', paragraphs: ['Record the primary dispatcher, published desk hours and escalation contact. Clarify who handles an active load if your regular contact is unavailable, and whether a particular load requires communication outside normal hours. Do not infer continuous coverage from a phone number alone.', 'Keep carrier owned accounts under carrier control. Agree the authorized access method, document sharing process and where the final load records will be stored. Sensitive carrier documents should go through the agreed channel; an ordinary website inquiry is enough to start the discussion.'] },
      { id: 'handover', title: 'Read cancellation and handover terms before the first booking', paragraphs: ['Review notice requirements, any minimum term, fees still owed and the process for ending access. List how loads already booked will be completed, who will send outstanding delivery records and how open accessorial requests will be followed up. Ending a search relationship does not make an active shipment disappear.', 'FMCSA’s guidance addresses dispatch relationships and the activities that can require broker authority. Use that official guidance for role questions and seek qualified advice about legal clauses you do not understand. Ask the provider to resolve unanswered operational and billing questions in writing before signing.'] },
    ],
    checklistTitle: 'Before signing a dispatch agreement',
    checklist: ['Correct business names and covered trucks', 'Written tasks, approval contacts and support hours', 'Exact percentage, billing base and invoice timing', 'Access, cancellation and active load handover terms'],
    faqs: [
      { question: 'Is a dispatch agreement the same as a rate confirmation?', answer: 'No. The dispatch agreement describes the carrier’s service relationship with the dispatcher. A rate confirmation records terms for a particular load. Review and retain both.' },
      { question: 'Does a dispatch percentage apply to fuel surcharge?', answer: 'The billing base in the service agreement determines that. Ask for an example showing linehaul, fuel surcharge and accessorials before comparing percentage quotes.' },
      { question: 'Can I keep booking some loads myself?', answer: 'Discuss it explicitly. Agree how the truck calendar is shared, who communicates on each load and whether any fee applies to loads the carrier books independently.' },
      { question: 'Does this checklist replace contract advice?', answer: 'No. It helps organize operational questions. Have a qualified adviser review legal terms, liability or obligations that are unclear for your particular arrangement.' },
    ],
    related: [{ label: 'Dispatch fees by equipment', href: '/resources/truck-dispatch-fees' }, { label: 'Choose a truck dispatcher', href: '/resources/how-to-choose-a-truck-dispatcher' }, { label: 'Dispatcher and freight broker roles', href: '/resources/truck-dispatcher-vs-freight-broker' }, { label: 'Published dispatch pricing', href: '/pricing' }],
    sources: [{ label: 'FMCSA: definitions of broker and bona fide agents', href: 'https://www.fmcsa.dot.gov/regulations/federal-register-documents/2023-13080' }],
  },
  {
    slug: 'fuel-surcharge-calculation-for-carriers',
    title: 'Fuel surcharge calculation: a practical guide for carriers',
    metaTitle: 'Fuel Surcharge Calculation for Trucking Carriers',
    description: 'Understand diesel fuel surcharge inputs, index dates, mileage and invoice checks with a worked example. Confirm the actual formula in your load agreement.',
    eyebrow: 'Carrier guide · Understand the fuel line on the rate',
    published: '2026-10-30', readTime: '6 minute read',
    intro: 'A fuel surcharge is a contract defined charge used to account for fuel costs. To calculate or verify it, you need the agreed formula, reference price, base price, mileage and effective date. A diesel price on its own is not a surcharge. Work from the written load or lane terms, then compare the total compensation with the cost of the trip.',
    highlights: ['Separate the index from the agreement', 'Follow a transparent worked example', 'Check the final invoice and total trip'],
    sections: [
      { id: 'index', title: 'EIA publishes diesel prices; it does not set your surcharge', paragraphs: ['The U.S. Energy Information Administration publishes retail on highway diesel price data. EIA explains that companies choose their own fuel surcharge methods; the agency does not calculate, regulate or recommend the surcharge charged by a carrier.', 'If your agreement refers to EIA, identify the exact series, geography, publication date and effective week. A national average and a regional average are different inputs. Save the relevant dated reference with the calculation instead of substituting today’s number into an older load.'] },
      { id: 'inputs', title: 'Get every input before calculating', paragraphs: ['A formula may use a price difference divided by an agreed fuel efficiency factor, a published cents per mile table or another structure. Some quotes state one all in amount instead. Use the method actually agreed for the load; do not add an extra charge because another company uses one.', 'Clarify rounding, minimum or maximum adjustments, treatment of a price below the base and which miles qualify. The agreement may use a particular mileage source rather than the distance shown by your preferred map. These choices can change the result.'], table: { caption: 'Inputs to confirm in the written fuel surcharge terms', headers: ['Input', 'What to record'], rows: [['Reference price', 'Named diesel index, region and dated value'], ['Base price', 'The price already assumed in the contracted rate'], ['Calculation method', 'Formula or table, efficiency factor and rounding rule'], ['Eligible mileage', 'Mileage source and whether loaded, empty or other miles count'], ['Timing', 'Which index date applies to the shipment'], ['Invoice treatment', 'Separate fuel line or an included all in rate']] } },
      { id: 'example', title: 'Worked example: price difference divided by an agreed factor', paragraphs: ['Suppose a hypothetical contract specifies a $4.20 per gallon reference price, a $1.50 base price and a 6 mile per gallon factor. Subtracting the base from the reference gives $2.70 per gallon. Dividing $2.70 by 6 gives a surcharge of $0.45 per eligible mile.', 'If the same agreement specifies 600 eligible miles, the surcharge is 600 × $0.45 = $270. With $1,800 linehaul, the combined compensation would be $2,070 before any separately agreed accessorials. These are invented example inputs, not current EIA prices, a Rai Dispatch quote or a recommended contract formula.'], table: { caption: 'Hypothetical arithmetic only: use your agreement’s inputs', headers: ['Step', 'Calculation', 'Result'], rows: [['Price difference', '$4.20 − $1.50', '$2.70 per gallon'], ['Per mile adjustment', '$2.70 ÷ 6 miles per gallon', '$0.45 per mile'], ['Shipment surcharge', '600 eligible miles × $0.45', '$270'], ['Linehaul plus surcharge', '$1,800 + $270', '$2,070']] } },
      { id: 'total-trip', title: 'Keep surcharge miles separate from your operating miles', paragraphs: ['A contract may pay a surcharge on loaded miles while the truck also travels empty to pickup or after delivery. Record both the compensated mileage and the actual trip mileage. The first is needed to check the invoice; the second helps the carrier evaluate the work.', 'Continuing the example, 100 empty miles added to 600 loaded miles creates 700 known trip miles. The $2,070 combined compensation equals about $2.96 per known mile before dispatch fees and operating expenses. If another return obligation exists, include those miles too. A fuel surcharge does not automatically cover every fuel expense or establish profit.'] },
      { id: 'fees', title: 'Clarify how fuel affects dispatch billing', paragraphs: [`Rai Dispatch publishes equipment specific percentage fees of ${DISPATCH_RATE_RANGE}. Whether a separately stated fuel surcharge belongs in the dispatch billing base must be clear in the agreement. Ask for the linehaul, fuel and accessorial treatment to be shown in a sample calculation.`, 'Also distinguish the fuel adjustment from factoring charges, toll reimbursement and other costs. Putting several unrelated items into a single “fuel” line makes a comparison harder to review. Use consistent labels and retain the rate confirmation that supports each item.'] },
      { id: 'reconcile', title: 'Check the invoice against the approved version', paragraphs: ['Before submission, compare the final fuel line with the agreed index date, eligible mileage, formula and rounding. If the route or appointment changed, confirm whether the change affects the calculation rather than making an automatic adjustment.', 'Keep a short worksheet showing the inputs, arithmetic, source date and approval reference. When a discrepancy appears, send that worksheet with a specific question: which input differs, and what do the agreed terms require? A traceable calculation is easier to resolve than a total with no explanation.'] },
    ],
    checklistTitle: 'Fuel surcharge verification sheet',
    checklist: ['Written formula or rate table', 'Exact index, region and effective date', 'Base price, efficiency factor and eligible mileage', 'Rounding, all in treatment and dispatch billing base'],
    faqs: [
      { question: 'Is there an official universal fuel surcharge rate?', answer: 'No. EIA publishes diesel price data but does not set a universal surcharge. Use the formula or table agreed with the responsible contracting party.' },
      { question: 'Can I add a fuel surcharge to an all in load rate?', answer: 'Do not assume an additional charge is payable. Review the agreed compensation and obtain written clarification or an approved change before treating an extra fuel line as due.' },
      { question: 'Should I use the latest diesel price for every invoice?', answer: 'Use the date and series specified by the agreement. A shipment from an earlier week may have a different applicable reference.' },
      { question: 'Does the surcharge equal my actual fuel spend?', answer: 'Not necessarily. A formula can use an index, agreed efficiency factor and defined mileage that differ from your purchases and total trip. Review actual expenses separately.' },
    ],
    related: [{ label: 'Freight rate per mile explained', href: '/resources/evaluate-freight-rate-per-mile' }, { label: 'Dispatch agreement checklist', href: '/resources/truck-dispatch-service-agreement-checklist' }, { label: 'Freight rate negotiation support', href: '/services/rate-negotiation' }, { label: 'Rate confirmation checklist', href: '/resources/rate-confirmation-checklist' }],
    sources: [{ label: 'EIA: diesel fuel surcharges and the role of price data', href: 'https://www.eia.gov/energyexplained/diesel-fuel/diesel-fuel-surcharges.php' }, { label: 'EIA: weekly gasoline and diesel fuel price data', href: 'https://www.eia.gov/petroleum/gasdiesel/' }],
  },
  {
    slug: 'verify-freight-broker-identity',
    title: 'How to verify a freight broker’s identity before booking',
    metaTitle: 'Verify Freight Broker Identity | Carrier Checklist',
    description: 'Check broker identity, official records, contact details and changed load instructions. A practical verification workflow for owner operators and dispatch teams.',
    eyebrow: 'Carrier guide · Know who is actually offering the load',
    published: '2026-10-30', readTime: '6 minute read',
    intro: 'A familiar business name or a valid MC number does not prove that the person messaging you represents that business. Verify the entity, the contact and the particular load before sharing sensitive documents or accepting instructions. Use the checks below as a repeatable carrier workflow, with an independent callback when details do not match.',
    highlights: ['Check the entity and the contact', 'Verify changes independently', 'Keep a useful decision record'],
    sections: [
      { id: 'entity', title: 'Start with the exact entity named on the load', paragraphs: ['Collect the legal business name, relevant identifiers, contact name, phone number, email address and load reference. Compare them across the posting, setup request and rate confirmation. Note a mismatch as an unanswered question rather than silently choosing whichever name looks familiar.', 'FMCSA directs users to its Licensing and Insurance system for interstate authority and related registration information. Check the actual transportation entity and current status through the official source. Registration information is one part of the review; it is not a guarantee that a particular message is authentic or that payment will be made.'] },
      { id: 'contact', title: 'Use an independently obtained contact to verify the offer', paragraphs: ['FMCSA’s fraud guidance recommends checking phone numbers against SAFER and calling the listed business when the supplied number differs. A search advertisement, email signature or document sent by the same unknown person is not an independent confirmation. Reach the organization through a separately verified channel.', 'On the call, ask whether the named contact works with the business and whether the load reference, route and instructions are theirs. Record whom you spoke with, the number used, the date and the result. If the person cannot confirm the transaction, pause the booking and resolve the discrepancy before moving forward.'], table: { caption: 'Keep identity verification separate from commercial approval', headers: ['Check', 'Question it answers', 'What it does not establish'], rows: [['Official entity record', 'What entity and status are recorded?', 'That the person messaging you represents it'], ['Independent callback', 'Does the business confirm this contact and load?', 'That every commercial term is acceptable'], ['Written load review', 'Do the approved route, pay and requirements match?', 'A guarantee of payment or absence of fraud'], ['Carrier or factoring review', 'Does the transaction meet your own acceptance process?', 'Permission to ignore a later instruction mismatch']] } },
      { id: 'documents', title: 'Review documents without rushing the identity check', paragraphs: ['Examine the sender address, business names, load numbers and document version. A professional looking rate confirmation or insurance certificate can still be false. Be particularly careful with a request to bypass your normal setup process, send credentials or disclose sensitive business records through an unfamiliar link.', 'Share only the documents required for the verified transaction through the agreed process. Keep carrier owned account access under your control. A dispatcher can help organize the checks and records, while the carrier’s authorized person decides whether the arrangement meets its requirements.'] },
      { id: 'changes', title: 'Treat changed payment or delivery instructions as a new check', paragraphs: ['A transaction that was verified yesterday can still receive a suspicious change today. Confirm requests for a new payment destination, a different consignee, an unfamiliar pickup identity or a last minute redirect through the established business contact. Do not rely only on the reply address in the change request.', 'For example, an email claims the broker has moved a delivery and asks the driver to use a different company name at the gate. The next step is an independent callback to the verified broker contact, a review with the carrier and clear documented instructions. Urgency does not resolve the identity question.'] },
      { id: 'pause', title: 'Give the driver a clear way to stop and escalate uncertainty', paragraphs: ['Tell the driver whom to contact if the pickup, cargo, destination or identity instructions differ from the approved load. Share verified references and contacts before arrival. A driver should not have to decide alone whether a message from an unfamiliar number changes the shipment.', 'When concerns arise after pickup, protect the cargo, preserve the messages and contact the verified parties and appropriate authorities as needed. Follow FMCSA’s current reporting guidance. Avoid accusing an unrelated company simply because its name or identifier appears in a suspicious message; its identity may also have been misused.'] },
      { id: 'record', title: 'Keep the decision trail concise and usable', paragraphs: ['Store the official record check, callback result, approved rate confirmation, carrier approval and any later changes under the same load reference. A compact record is more useful than screenshots scattered across several phones. Restrict access to people who need the information for the operation.', 'After a discrepancy is resolved, tell everyone involved which version is current. If it remains unresolved, record why the load was declined or held for review. Consistent checks improve the information behind a booking, but no checklist can promise that every fraudulent approach will be detected.'] },
    ],
    checklistTitle: 'Before approving an unfamiliar broker load',
    checklist: ['Exact entity, identifiers and official status', 'Independently verified contact and load reference', 'Matching written route, compensation and instructions', 'Named escalation contact and saved verification record'],
    faqs: [
      { question: 'Is a valid MC number enough to verify a broker?', answer: 'No. Someone can misuse a legitimate business’s identity. Check the official entity information and independently confirm the person and load with that business.' },
      { question: 'Does factoring approval replace identity verification?', answer: 'No. Follow your factoring provider’s requirements, but also verify who is offering the load and whether the instructions are authentic. They answer different questions.' },
      { question: 'What if the phone number differs from the official record?', answer: 'FMCSA advises calling the number listed in SAFER to discuss the transaction. Resolve the mismatch through a reliable independent contact before relying on the offer.' },
      { question: 'Does a dispatch service guarantee broker payment?', answer: 'No. Dispatch communication and document support do not guarantee a counterparty’s payment. Review payment terms and your own acceptance process separately.' },
    ],
    related: [{ label: 'New authority broker approval', href: '/resources/new-authority-broker-approval' }, { label: 'Rate confirmation review', href: '/resources/rate-confirmation-checklist' }, { label: 'Broker communication support', href: '/services/broker-communication' }, { label: 'Dispatch paperwork support', href: '/services/paperwork-support' }],
    sources: [{ label: 'FMCSA: broker and carrier fraud and identity theft', href: 'https://www.fmcsa.dot.gov/mission/help/broker-and-carrier-fraud-and-identity-theft' }, { label: 'FMCSA: where to check interstate authority and insurance information', href: 'https://www.fmcsa.dot.gov/faq/where-do-i-go-look-motor-carrier-broker-or-freight-forwarders-interstate-operating-authority' }, { label: 'FMCSA SAFER: official company information', href: 'https://safer.fmcsa.dot.gov/' }],
  },
  {
    slug: 'reefer-load-temperature-checklist',
    title: 'Reefer load checklist: temperature instructions before booking',
    metaTitle: 'Reefer Load Temperature & Booking Checklist',
    description: 'Prepare a reefer load brief covering written temperature instructions, operating mode, trailer preparation, appointments, records and changes during transit.',
    eyebrow: 'Carrier guide · Make refrigerated load instructions usable',
    published: '2026-10-30', readTime: '6 minute read',
    intro: 'Before accepting refrigerated freight, collect the written handling instructions and confirm that the trailer, unit, driver and schedule can meet them. A commodity name and a temperature number leave important questions unanswered. This worksheet helps a carrier and dispatcher organize the booking review; the shipper’s instructions and the carrier’s equipment procedures govern the actual load.',
    highlights: ['A written load temperature brief', 'Preparation and appointment planning', 'A clear change and escalation record'],
    sections: [
      { id: 'instructions', title: 'Ask for the complete written temperature instructions', paragraphs: ['Record the commodity, required setpoint, units of measurement, operating mode and any specified range or monitoring requirements. Distinguish the refrigeration unit setpoint from any product temperature acceptance criteria. If the paperwork uses different figures or wording, seek clarification from the authorized party before the carrier approves the load.', 'Do not choose a setting from a generic commodity list or from a previous shipment that looked similar. Different products, packaging and shipper requirements can call for different handling. The dispatcher’s role is to obtain and communicate the instructions, not to independently select a safe cargo temperature.'], table: { caption: 'Reefer load brief to complete with the authorized shipping or brokerage contact', headers: ['Topic', 'Details to obtain'], rows: [['Cargo', 'Commodity, packaging, weight, pallet count and special handling'], ['Temperature', 'Written setpoint, units, permitted range if specified and operating mode'], ['Preparation', 'Pre cooling, cleanliness, washout and prior load requirements'], ['Loading', 'Appointment, loading process, seal procedure and responsible contacts'], ['Monitoring', 'Required records, reporting method and exception contact'], ['Delivery', 'Appointment, receiving requirements and document handover']] } },
      { id: 'preparation', title: 'Include trailer preparation in the available time', paragraphs: ['Tell the dispatcher when the current load will actually finish and what preparation follows. A washout, inspection, fuel stop or precooling requirement may affect when the truck can reach the next pickup. An empty trailer is not necessarily ready for every refrigerated shipment.', 'FDA’s sanitary transportation framework addresses sanitary practices for covered food transportation. Its guidance discusses written specifications, preparation and temperature control responsibilities, with requirements depending on the activity and agreement. Review the official guidance for your operation rather than assuming every reefer load has identical obligations.', 'Keep requested preparation records with the load file. If a washout certificate or other document is specified, confirm who receives it and when. A dispatcher can remind the parties about missing information, while the carrier confirms equipment condition and readiness.'] },
      { id: 'appointments', title: 'Review the pickup and delivery plan as one schedule', paragraphs: ['Clarify the appointment date, time zone, check in procedure and receiving hours at every stop. For a multi stop load, review the sequence and any instructions for opening doors, seals or monitoring. Do not assume a receiver will accept early arrival or that a delayed pickup automatically moves delivery.', 'Add the preparation and handling time to the trip comparison. A pickup that appears close to the current delivery may still be unsuitable if the truck must first complete an agreed cleaning process. Discuss waiting, lumper procedures and documentation before pickup so the driver has the relevant contacts.'] },
      { id: 'conflict-example', title: 'Example: resolve conflicting instructions before relying on them', paragraphs: ['Suppose a rate confirmation specifies one operating mode, while a later message requests a different mode. Keep both records and identify the conflict plainly. Ask the authorized shipping or brokerage contact for a clear written correction, and have the carrier confirm that the revised requirement is acceptable before proceeding on that basis.', 'Send the resolved version to the driver and mark the earlier instruction as superseded. Record the source, time and load reference. This example is a communication process; it is not an instruction to change a unit setting, accept questionable cargo or decide whether a product is safe.'] },
      { id: 'exceptions', title: 'Agree the response to a temperature or equipment concern', paragraphs: ['Before departure, identify who should receive an equipment alarm, a temperature record concern, a long loading delay or a delivery discrepancy. The driver should follow the carrier’s safety and equipment procedures and promptly communicate the facts through the agreed channel.', 'Preserve the actual readings, timestamps, messages and available equipment records. Avoid describing an uncertain cause as a confirmed diagnosis. The appropriate authorized parties need accurate information to decide the next step; dispatch should not invent a product disposition or promise that a claim will be avoided.'] },
      { id: 'closeout', title: 'Close the load with a complete record and realistic next plan', paragraphs: [`Keep signed delivery records, approved instructions, receipts and any exception correspondence together. Rai Dispatch supports the agreed booking, communication and document workflow at a published ${getDispatchRateLabel('reefer')} reefer dispatch fee, with the billing base confirmed in writing.`, 'After delivery, update the truck’s location, condition and next available time. Include any cleaning or preparation before the next search. Reviewing what changed during the trip helps improve the next booking brief without treating an unusual delay as a universal rule for that lane.'] },
    ],
    checklistTitle: 'Before carrier approval of a reefer load',
    checklist: ['Complete written temperature and mode instructions', 'Carrier confirmed unit capability and preparation plan', 'Pickup, delivery and multi stop requirements', 'Monitoring records and a verified exception contact'],
    faqs: [
      { question: 'Can the dispatcher choose the reefer temperature?', answer: 'No. Obtain the authorized shipment instructions in writing. Dispatch helps clarify and communicate them; the carrier operates the equipment and evaluates its ability to meet the requirements.' },
      { question: 'Is a washout required before every reefer load?', answer: 'Do not apply a universal assumption. Check the shipment’s sanitation and prior load requirements and the carrier’s procedures, including applicable food transportation rules.' },
      { question: 'What if the written instructions conflict?', answer: 'Flag the discrepancy, obtain clarification from the authorized party and keep the corrected version with the load. Make sure the carrier and driver receive the same final instructions.' },
      { question: 'Does the reefer dispatch fee include washouts or lumper charges?', answer: 'The dispatch fee covers the agreed service. Operating expenses and third party charges are separate subjects; confirm any reimbursement process and approvals in the load terms.' },
    ],
    related: [{ label: 'Reefer dispatch services', href: '/equipment/reefer' }, { label: 'Appointment scheduling support', href: '/services/scheduling' }, { label: 'Detention and accessorial documentation', href: '/resources/detention-layover-tonu-documentation' }, { label: 'Rate confirmation checklist', href: '/resources/rate-confirmation-checklist' }],
    sources: [{ label: 'FDA: sanitary transportation of human and animal food', href: 'https://www.fda.gov/food/food-safety-modernization-act-fsma/fsma-final-rule-sanitary-transportation-human-and-animal-food' }, { label: 'FDA: small entity guide to sanitary transportation requirements', href: 'https://www.fda.gov/regulatory-information/search-fda-guidance-documents/small-entity-compliance-guide-sanitary-transportation-human-and-animal-food-what-you-need-know-about' }],
  },
  {
    slug: 'flatbed-load-tarping-checklist',
    title: 'Flatbed load checklist: dimensions, tarping and loading details',
    metaTitle: 'Flatbed Load & Tarping Checklist for Carriers',
    description: 'Review flatbed freight before booking with a cargo, tarp, loading site and appointment worksheet. Compare the work behind the rate and clarify written terms.',
    eyebrow: 'Carrier guide · Understand the job on the deck',
    published: '2026-10-30', readTime: '6 minute read',
    intro: 'A flatbed load review should establish what is being moved, how it will be loaded, how it must be protected and whether the carrier has the right equipment and capability. The rate and mileage come after those facts. Use this checklist to prepare a complete booking discussion for flatbed or step deck freight, with the carrier making the securement and operating decisions.',
    highlights: ['Detailed cargo and deck information', 'Tarping and loading work clarified', 'Rate terms matched to the actual job'],
    sections: [
      { id: 'cargo', title: 'Collect dimensions for the actual pieces', paragraphs: ['Request the commodity, number of pieces, individual dimensions, total weight and loading arrangement. Ask whether dimensions include packaging, protrusions or attachments. A generic label such as “machinery” is not enough to determine whether the shipment fits the available deck.', 'Compare the cargo information with the actual trailer configuration, usable deck space and carrier confirmed capacity. For step deck equipment, identify which portion of the deck is intended for each piece. If a dimension, weight or routing issue suggests specialized movement, get the appropriate capability review before treating it as an ordinary booking.'], table: { caption: 'Open deck load review worksheet', headers: ['Information', 'Question to resolve before approval'], rows: [['Cargo dimensions and weight', 'Are the measurements complete for every piece and package?'], ['Deck and loading arrangement', 'Where will the pieces sit and how will they be loaded?'], ['Protection requirements', 'What tarp coverage, material or other protection is specified?'], ['Site access and equipment', 'Who supplies the crane, forklift or other loading equipment?'], ['Carrier equipment', 'Does the carrier have appropriate gear and capability for this load?'], ['Schedule and rate', 'Are handling time, stops and agreed charges reflected in the terms?']] } },
      { id: 'tarps', title: 'Clarify tarping requirements beyond “tarps required”', paragraphs: ['Ask what must be covered, the cargo profile and the type or extent of protection specified. Give the actual dimensions and condition of the tarps available. The required drop or coverage needs to match the loaded cargo shape, not only the trailer width.', 'Confirm where tarping can be performed, any site procedures and how the driver will safely access the work area. Tell the broker about work the carrier does not accept. A dispatcher should not promise a particular protection method until the carrier has reviewed the cargo and equipment information.'] },
      { id: 'securement', title: 'Keep cargo protection and securement as separate reviews', paragraphs: ['A tarp protects cargo under the agreed handling instructions; it does not establish that the cargo is safely secured. FMCSA publishes general and commodity specific securement requirements. The carrier and driver must determine the appropriate method and equipment for the actual load.', 'Provide the dispatcher with the gear available, while keeping securement decisions with the qualified carrier personnel. Cargo shape, weight, contact points and commodity can matter. This booking worksheet is not a tiedown calculation and does not specify how many chains or straps a load needs.'], bullets: ['Resolve missing cargo dimensions and loading details.', 'Identify special or commodity specific requirements for carrier review.', 'Confirm that the driver has a safe, workable loading and protection plan.', 'Do not let a posted rate substitute for equipment or capability checks.'] },
      { id: 'sites', title: 'Check the work at both facilities', paragraphs: ['Obtain pickup and delivery contacts, appointments, operating hours and access instructions. Ask about crane or forklift availability, who performs loading and unloading, and whether the site requires additional equipment or procedures. A suitable trailer can still be a poor fit for an inaccessible job site.', 'For multiple picks or drops, review the full sequence and how each piece will be reached. A later stop may require removing and replacing protection or changing the loading arrangement. Present that extra work and time during the rate discussion rather than discovering it after arrival.'] },
      { id: 'rate-example', title: 'Compare handling time alongside the rate', paragraphs: ['Consider two hypothetical loads with the same 400 loaded miles and the same offered pay. One is a single pickup and delivery with straightforward handling. The other requires two pickups and additional tarping work. Identical mileage and compensation do not make the jobs equivalent.', 'Record the known extra travel, appointment windows and expected tasks for each option. Ask how additional stops, protection work and waiting are compensated and documented. Keep assumptions marked as estimates until confirmed. The carrier can then decide whether the total work fits its schedule and costs.'] },
      { id: 'changes', title: 'Recheck the booking when the cargo changes', paragraphs: ['If the shipper adds a piece, revises the dimensions or changes the loading method, compare the new information with the approved plan. Get carrier review and the appropriate written changes before relying on the original booking. The dispatcher can coordinate clarification but cannot authorize an unsuitable load.', `Rai Dispatch’s flatbed fee is ${getDispatchRateLabel('flatbed')}; step deck dispatch is ${getDispatchRateLabel('step-deck')} under the published equipment schedule. Confirm classification, billing base and scope before service. Keep the final instructions and approved charges with the rate confirmation for the driver and office.`] },
    ],
    checklistTitle: 'Before accepting open deck freight',
    checklist: ['Complete piece dimensions, weight and loading plan', 'Written protection requirements and actual tarp inventory', 'Carrier reviewed securement capability and site access', 'Appointments, extra work, approval and final rate terms'],
    faqs: [
      { question: 'Do all flatbed loads need tarps?', answer: 'No. Requirements depend on the commodity and shipment instructions. Confirm what protection is required before the carrier approves the load.' },
      { question: 'Is tarping compensation always separate?', answer: 'No universal billing treatment applies. Ask whether it is included in the quoted rate or separately agreed, and keep the approved amount and conditions in writing.' },
      { question: 'Can a dispatcher approve the securement plan?', answer: 'Dispatch can collect and communicate the cargo details. The carrier and driver must make the securement and safe operation decisions using the applicable requirements and their actual equipment.' },
      { question: 'Should step deck loads use the same review?', answer: 'The same questions are useful, but the deck configuration, cargo placement and clearance need their own review. Do not treat step deck and standard flatbed dimensions as interchangeable.' },
    ],
    related: [{ label: 'Flatbed dispatch services', href: '/equipment/flatbed' }, { label: 'Step deck dispatch', href: '/equipment/step-deck' }, { label: 'Freight rate negotiation', href: '/services/rate-negotiation' }, { label: 'Hotshot load planning', href: '/resources/hotshot-load-planning-checklist' }],
    sources: [{ label: 'FMCSA: general and commodity specific cargo securement rules', href: 'https://www.fmcsa.dot.gov/regulations/cargo-securement/cargo-securement-rules' }],
  },
  {
    slug: 'power-only-trailer-interchange-checklist',
    title: 'Power only loads: trailer handoff and return checklist',
    metaTitle: 'Power Only & Trailer Interchange Load Checklist',
    description: 'Review a power only load from trailer pickup to return. Clarify equipment identity, written trailer terms, inspections, responsibility, mileage and release records.',
    eyebrow: 'Carrier guide · Review the whole trailer obligation',
    published: '2026-10-30', readTime: '6 minute read',
    intro: 'A power only load involves more than pulling a trailer from pickup to delivery. Before booking, identify whose trailer the carrier will use, the written terms for that use, the pickup condition and the final return or release requirement. This checklist organizes the dispatch discussion while the carrier and its advisers confirm equipment, agreement and insurance suitability.',
    highlights: ['Trailer identity and responsibility', 'Pickup to return trip comparison', 'A documented final handoff'],
    sections: [
      { id: 'arrangement', title: 'Identify the actual trailer arrangement', paragraphs: ['Ask whether the job is a loaded trailer move, an empty reposition, a live load arrangement or work involving a trailer pool. Identify the owner or responsible equipment provider and the party issuing the operating instructions. A listing marked “power only” does not answer those questions.', 'Obtain the relevant trailer use or interchange agreement before acceptance where one applies. Ask the insurer or qualified adviser to assess the actual terms and required coverage. Trailer interchange and other non owned trailer arrangements should not be treated as interchangeable insurance promises based only on the wording of a load post.'] },
      { id: 'handoff', title: 'Record the trailer and the handoff instructions', paragraphs: ['Get the trailer identifier, location, release reference, yard contact and pickup window. Confirm whether the trailer is loaded and ready, whether it will need a live load and whether any gate or access process applies. Ask how the carrier will confirm that it has been given the correct trailer.', 'Arrange a clear record of the handoff and any visible concerns through the equipment provider’s process. Photos can support that record when permitted, but a photo is not a substitute for the carrier’s required inspection. FMCSA’s vehicle inspection guidance explains the driver’s responsibility to be satisfied that the vehicle is in safe operating condition.'], table: { caption: 'Questions to answer for every power only trailer move', headers: ['Stage', 'Information to confirm'], rows: [['Before booking', 'Trailer arrangement, written responsibilities and carrier acceptance'], ['Pickup', 'Trailer identifier, condition, location, readiness and release contact'], ['During the trip', 'Approved route, appointments and contacts for equipment issues'], ['After delivery', 'Return location, deadline, remaining mileage and release process'], ['Closeout', 'Documented handoff, receipts and any unresolved equipment or billing issue']] } },
      { id: 'responsibility', title: 'Clarify what happens if the trailer is not ready or has a problem', paragraphs: ['Identify who authorizes repairs, substitutions or a changed pickup, and how the carrier reports a condition concern. Ask what happens if the trailer is missing, not released, unsuitable or unavailable at the promised time. The driver should have a verified contact before arriving at the yard.', 'Keep an operational concern separate from a billing question. First obtain an appropriate safe and workable decision from the responsible parties. Then document the timing, instructions and agreed compensation. A dispatcher can coordinate the calls; it cannot decide that defective equipment is safe or create insurance coverage.'] },
      { id: 'miles-example', title: 'Count the return miles before comparing the offer', paragraphs: ['For a hypothetical $1,500 trailer move, suppose the tractor travels 40 empty miles to pickup, pulls the loaded trailer 500 miles and must then take it 120 miles to the required return yard. The known obligation is 660 miles, not only the 500 loaded miles. Gross compensation is about $2.27 per known mile before fees and operating expenses.', `At the published ${getDispatchRateLabel('power-only')} power only dispatch rate on an agreed $1,500 billing base, the fee would be $${1500 * getDispatchRate('power-only') / 100}. The remaining $${1500 - 1500 * getDispatchRate('power-only') / 100} is about $${((1500 - 1500 * getDispatchRate('power-only') / 100) / 660).toFixed(2)} per known mile before fuel, maintenance, insurance, driver pay and other costs. Add any further tractor reposition to your operating comparison. These are illustrative inputs, not market rates.`, 'Also count yard hours and the return deadline. A required return to a closed facility can affect when the tractor is available for its next job, even when the map shows a short drive.'] },
      { id: 'changes', title: 'Reconfirm responsibility when the plan changes', paragraphs: ['A substitute trailer, revised return yard or delayed release can change more than mileage. Obtain the replacement identifiers and authorized instructions, then have the carrier reassess the arrangement before proceeding. Do not assume an earlier approval automatically covers different equipment or terms.', 'If the booking is cancelled after pickup, ask the responsible party for written return or release instructions. Preserve the records of possession and handoff. Unclear instructions need escalation through verified contacts rather than an improvised trailer drop.'] },
      { id: 'release', title: 'Finish with a documented return or release', paragraphs: ['Confirm the final location, recipient and the time responsibility is handed back under the arrangement. Keep the equipment provider’s required receipt or release record, along with any photos, condition notes and correspondence. A delivery receipt for the cargo may not document the separate trailer return.', 'Update dispatch availability only after accounting for that obligation. Send the carrier office the final records and list unresolved issues separately. The next load search should begin from the tractor’s actual location and readiness, with no unrecorded trailer task left behind.'] },
    ],
    checklistTitle: 'Before a power only booking',
    checklist: ['Trailer identity, owner and written use terms', 'Carrier and insurer review of responsibilities', 'Pickup readiness, inspection and issue contacts', 'Return location, deadline, full mileage and release record'],
    faqs: [
      { question: 'Does power only always mean drop and hook?', answer: 'No. The arrangement may include live loading, empty repositioning or other trailer obligations. Confirm the exact pickup and delivery process before booking.' },
      { question: 'Is trailer return mileage always paid separately?', answer: 'No. Review the approved compensation and the complete trailer obligation. Ask for written clarification of any separate charges before accepting the load.' },
      { question: 'Does my existing insurance automatically cover the trailer?', answer: 'Do not assume coverage from the equipment label. Give the actual agreement and trailer arrangement to your insurer or qualified adviser for confirmation.' },
      { question: 'What records should I keep after returning the trailer?', answer: 'Retain the required handoff or release record, trailer identifier, time, location and any condition notes or correspondence, following the agreement and carrier procedures.' },
    ],
    related: [{ label: 'Power only dispatch services', href: '/equipment/power-only' }, { label: 'Backhaul and return load planning', href: '/services/backhaul-dispatch' }, { label: 'Freight rate per mile guide', href: '/resources/evaluate-freight-rate-per-mile' }, { label: 'Rate confirmation checklist', href: '/resources/rate-confirmation-checklist' }],
    sources: [{ label: 'FMCSA Motor Carrier Safety Planner: vehicle inspections', href: 'https://csa.fmcsa.dot.gov/SafetyPlanner/MyFiles/SubSections.aspx?ch=22&eta=89226&sec=65&sub=148' }],
  },
  {
    slug: 'hotshot-load-planning-checklist',
    title: 'Hotshot load planning: a checklist before accepting freight',
    metaTitle: 'Hotshot Load Planning & Booking Checklist',
    description: 'Plan hotshot loads around actual truck and trailer capability, cargo dimensions, loading, securement, appointments and total miles before carrier approval.',
    eyebrow: 'Carrier guide · Match the shipment to your actual setup',
    published: '2026-10-30', readTime: '6 minute read',
    intro: 'A hotshot load needs to fit the truck, trailer and driver schedule. “Hotshot” does not define a universal payload or make an urgent pickup workable. Collect the equipment and shipment details, then compare the complete plan before approving the booking.',
    highlights: ['A specific truck and trailer profile', 'Cargo and schedule reviewed together', 'A complete trip fee example'],
    sections: [
      { id: 'profile', title: 'Use the actual combination, not a generic trailer label', paragraphs: ['Provide trailer type, usable deck dimensions, loading access and the carrier confirmed capacity of the complete combination. Include ramps, tarps and other available gear. Manufacturer ratings, vehicle configuration, cargo placement and the requirements of the actual operation need carrier review; an advertised trailer length is not a payload determination.', 'Keep the profile current after a truck, trailer or equipment change. If a dispatcher has been searching from the previous setup, say clearly what has changed before another load is proposed. A saved photo can help explain the configuration, but measurements and verified details are still needed.'], table: { caption: 'Hotshot load brief for the dispatch desk', headers: ['Provide', 'Explain'], rows: [['Truck and trailer configuration', 'The actual combination being offered for this load'], ['Usable dimensions and capacity', 'Carrier reviewed limits, deck space and loading access'], ['Cargo details', 'Piece dimensions, weight, commodity and handling requirements'], ['Equipment available', 'Ramps, tarps and relevant gear for carrier capability review'], ['Truck readiness', 'Current location, realistic available time and driver schedule'], ['Operating preferences', 'Pickup radius, destinations, home time and declined work']] } },
      { id: 'cargo', title: 'Review pieces, loading method and destination access', paragraphs: ['Ask whether each piece is self propelled, palletized, crated or otherwise packaged, and obtain its actual dimensions and weight. Confirm who loads and unloads, which equipment the facilities provide and what access is available at each stop. “Equipment move” can describe very different work.', 'If ramps are involved, the carrier must assess the relevant equipment ratings, configuration and method. Dispatch should not promise that a machine can be loaded merely because ramps are present. Resolve an uncertain loading plan with the responsible parties before the carrier commits the truck.'] },
      { id: 'securement', title: 'Confirm protection and securement capability', paragraphs: ['Clarify written tarping or other protection requirements and give the carrier the complete cargo details. FMCSA’s cargo securement guidance includes general and commodity specific requirements. The carrier and driver make the securement and safe operation decisions for the actual shipment.', 'Where dimensions, weight or the route suggest specialized restrictions, obtain the appropriate review before booking. State requirements and the actual route matter. Dispatch support does not itself supply permits or establish that a combination is legal for every road. Treat that review as a defined responsibility rather than an assumption attached to the hotshot label.'] },
      { id: 'appointments', title: 'Test urgency against realistic readiness', paragraphs: ['State when the truck can actually reach pickup, including completion of current work, equipment preparation and the drive to the facility. Confirm whether the requested time is an appointment, a ready time or a delivery deadline. Identify the time zone and the contact authorized to discuss changes.', 'For example, a truck expected to finish unloading late in the morning cannot be treated as already empty when reviewing a nearby urgent pickup. Update the estimated release time and have the carrier assess the whole trip. A deadline does not justify an unsafe schedule or skipping necessary preparation.'] },
      { id: 'partials', title: 'Review the whole route before adding a partial load', paragraphs: ['Spare deck space is only one part of a partial load decision. Check remaining capacity, cargo compatibility, access to each piece, stop order, appointments and written co loading restrictions. The carrier must approve the combined plan, and each booking must permit the intended arrangement.', 'A second pickup can make a first delivery unworkable even if both pieces physically fit. Write down the complete sequence before discussing the extra revenue. Include detours, waiting, additional handling and any need to remove or replace cargo protection.'] },
      { id: 'cost-example', title: 'Compare compensation across all known miles', paragraphs: ['Consider a hypothetical $1,200 load with 400 loaded miles, 60 empty miles to pickup and 40 miles to the required next location. The known trip totals 500 miles. Gross compensation is $2.40 per known mile, rather than the $3.00 figure obtained using loaded miles alone.', `At Rai Dispatch’s published ${getDispatchRateLabel('hotshot')} hotshot fee on an agreed $1,200 billing base, dispatch would cost $${1200 * getDispatchRate('hotshot') / 100}. The remaining $${1200 - 1200 * getDispatchRate('hotshot') / 100} is about $${((1200 - 1200 * getDispatchRate('hotshot') / 100) / 500).toFixed(2)} per known mile before operating expenses. These figures are illustrative, not offered rates or an income forecast.`, 'Add loading work, appointment time, tolls and your actual operating costs to the decision. A higher gross amount can still leave a poor fit for your working day or home time plan. Keep unconfirmed reloads separate from the compensation already agreed.'] },
      { id: 'approve', title: 'Approve the final written plan and update changes promptly', paragraphs: ['Review the rate confirmation against the cargo details, appointments, instructions and compensation the carrier approved. Keep the driver’s version current. If weight, dimensions or the loading method changes at pickup, raise the difference and obtain carrier review before relying on the original acceptance.', 'After delivery, retain the signed records and update actual availability for the next search. Share the difference between planned and actual miles or handling time. That feedback helps the dispatcher refine the next proposal for the particular truck and trailer you operate.'] },
    ],
    checklistTitle: 'Hotshot booking readiness',
    checklist: ['Current combination specifications and carrier reviewed capacity', 'Complete cargo, protection and loading information', 'Workable appointments and approved combined stop sequence', 'Total mile comparison, written terms and driver instructions'],
    faqs: [
      { question: 'Does a 40 foot hotshot trailer have a standard payload?', answer: 'No universal payload follows from length alone. The actual truck, trailer, ratings, loading arrangement and applicable operating limits need carrier review.' },
      { question: 'Can I combine two hotshot partial loads?', answer: 'Only after reviewing capability, cargo compatibility, access, timing and each load’s written restrictions. The carrier must approve the complete route and every booking.' },
      { question: 'Does hotshot mean the load must be expedited?', answer: 'Do not infer a particular deadline from the equipment label. Confirm the shipment’s actual pickup, delivery and handling requirements, including any urgent timing.' },
      { question: 'What is Rai Dispatch’s hotshot fee?', answer: `The published hotshot dispatch fee is ${getDispatchRateLabel('hotshot')} of the agreed revenue base on loads we book. A dedicated dispatcher and free setup are included; confirm detailed scope and billing terms before starting.` },
    ],
    related: [{ label: 'Hotshot dispatch services', href: '/equipment/hotshot' }, { label: 'Flatbed cargo and tarping review', href: '/resources/flatbed-load-tarping-checklist' }, { label: 'Partial truckload planning', href: '/resources/partial-truckload-vs-ltl' }, { label: 'Expedited dispatch support', href: '/services/expedited-dispatch' }, { label: 'Freight rate calculation', href: '/resources/evaluate-freight-rate-per-mile' }],
    sources: [{ label: 'FMCSA: cargo securement rules', href: 'https://www.fmcsa.dot.gov/regulations/cargo-securement/cargo-securement-rules' }, { label: 'WSDOT: an example of state specific commercial vehicle permit requirements', href: 'https://wsdot.wa.gov/travel/commercial-vehicles/commercial-vehicle-permits' }],
  },
];
